    const calc = new RegionalTaxCalculator(
      { "US": 0.08, "US-CA": 0.0875, "DE": 0.19 },
      0.05,
    );

    it("uses region-specific rate", () => {
      // 8% of 1000 = 80
      expect(calc.computeTaxCents(1000, "US")).toBe(80);
    });

    it("uses sub-region rate", () => {
      // 8.75% of 1000 = 87.5 → 87
      expect(calc.computeTaxCents(1000, "US-CA")).toBe(87);
    });

    it("falls back to default rate for unknown region", () => {
      // 5% of 1000 = 50
      expect(calc.computeTaxCents(1000, "JP")).toBe(50);
    });

    it("rounds down to nearest cent", () => {
      // 19% of 999 = 189.81 → 189
      expect(calc.computeTaxCents(999, "DE")).toBe(189);
    });

    it("returns 0 for zero taxable", () => {
      expect(calc.computeTaxCents(0, "US")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(calc.computeTaxCents(-100, "US")).toBe(0);
    });

    it("default rate of 0 yields 0 for unknown region", () => {
      const noDefault = new RegionalTaxCalculator({ "US": 0.08 });
      expect(noDefault.computeTaxCents(1000, "XX")).toBe(0);
    });
  });
});

