toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 2)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(9.99)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 49.99)).toThrow(RangeError);
    });

    it("accepts valid values", () => {
      expect(() => new FlatShippingCalculator(500, 5000)).not.toThrow();
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart without threshold", () => {
      const calc = new FlatShippingCalculator(799);
      expect(
        calc.computeShippingCents([makeLine("a", 100, 1)], 2000),
      ).toBe(799);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets freeOver threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(
        calc.computeShippingCents([makeLine("a", 100, 1)], 5000),
      ).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOver threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(
        calc.computeShippingCents([makeLine("a", 100, 1)], 7000),
      ).toBe(0);
    });

    it("returns flat fee when subtotal is just below freeOver threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(
        calc.computeShippingCents([makeLine("a", 100, 1)], 4999),
      ).toBe(799);
    });

    it("returns 0 when freeOverCents is 0 and subtotal is 0", () => {
      const calc = new FlatShippingCalculator(500, 0);
      expect(
        calc.computeShippingCents([makeLine("a", 100, 1)], 0),
      ).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer bracket values", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000.5, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents in bracket", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: 5.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            9.99,
          ),
      ).toThrow(RangeError);
    });

    it("accepts valid brackets and overflow", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [
              { upToGrams: 500, costCents: 300 },
              { upToGrams: 1000, costCents: 500 },
            ],
            800,
          ),
      ).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 500, costCents: 300 }, // intentionally out of order to test sorting
      { upToGrams: 2000, costCents: 800 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for cart with zero-weight items", () => {
      expect(
        calc.computeShippingCents([makeLine("a", undefined, 2)], 5000),
      ).toBe(0);
    });

    it("selects first bracket for weight within range", () => {
      // 300g → ≤500g bracket → 300 cents
      expect(
        calc.computeShippingCents([makeLine("a", 300, 1)], 5000),
      ).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      // exactly 500g → ≤500g bracket → 300 cents
      expect(
        calc.computeShippingCents([makeLine("a", 500, 1)], 5000),
      ).toBe(300);
    });

    it("selects next bracket when weight exceeds lower bound", () => {
      // 501g → ≤1000g bracket → 500 cents
      expect(
        calc.computeShippingCents([makeLine("a", 501, 1)], 5000),
      ).toBe(500);
    });

    it("selects highest bracket at its boundary", () => {
      // 2000g → ≤2000g bracket → 800 cents
      expect(
        calc.computeShippingCents([makeLine("a", 2000, 1)], 5000),
      ).toBe(800);
    });

    it("uses overflow (heaviest bracket) when weight exceeds all brackets", () => {
      // 3000g → overflow → defaults to heaviest bracket cost = 800
      expect(
        calc.computeShippingCents([makeLine("a", 3000, 1)], 5000),
      ).toBe(800);
    });

    it("uses explicit overflowCostCents when provided", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [
          { upToGrams: 500, costCents: 300 },
          { upToGrams: 1000, costCents: 500 },
        ],
        1200,
      );
      // 1500g > 1000g → overflow → 1200
      expect(
        calcWithOverflow.computeShippingCents([makeLine("a", 1500, 1)], 5000),
      ).toBe(1200);
    });

    it("sums weight across multiple lines", () => {
      // 400g * 2 + 300g * 1 = 1100g → ≤2000g bracket → 800
      const lines: CartLine[] = [
        makeLine("a", 400, 2),
        makeLine("b", 300, 1),
      ];
      expect(calc.computeShippingCents(lines, 5000)).toBe(800);
    });

    it("handles single bracket", () => {
      const single = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 500 },
      ]);
      expect(
        single.computeShippingCents([makeLine("a", 500, 1)], 5000),
      ).toBe(500);
      // overflow defaults to the single bracket cost
      expect(
        single.computeShippingCents([makeLine("a", 5000, 1)], 5000),
      ).toBe(500);
    });
  });
});

